import { CatalogItem, Era, MovieIndustry, StreamingPlatform } from '../types/catalog';

function eraFromYear(year: number): Era {
  if (year < 1980) return '1970s';
  if (year < 1990) return '1980s';
  if (year < 2000) return '1990s';
  if (year < 2010) return '2000s';
  if (year < 2020) return '2010s';
  return '2020s';
}

type MovieTuple = [
  id: string,
  title: string,
  year: number,
  creator: string,
  origin: string,
  rating: number,
  tags: string[],
  moods: string[],
  summary: string,
  whyNotable: string,
  extra?: {
    franchise?: string;
    platforms?: StreamingPlatform[];
    industry?: MovieIndustry;
    cast?: string[];
    language?: string;
    awards?: string;
    duration?: string;
    wikiPage?: string;
  }
];

function inferIndustry(origin: string): MovieIndustry {
  if (origin === 'India') return 'Bollywood';
  if (
    origin.includes('United States') ||
    origin.includes('UK') ||
    origin.includes('Australia') ||
    origin.includes('Canada') ||
    origin.includes('New Zealand')
  ) {
    return 'Hollywood';
  }
  return 'International';
}

function inferLanguage(origin: string, explicit?: string): string {
  if (explicit) return explicit;
  if (origin === 'India') return 'Hindi';
  if (origin === 'South Korea') return 'Korean';
  if (origin === 'Japan') return 'Japanese';
  if (origin === 'Hong Kong' || origin === 'Taiwan') return 'Mandarin / Cantonese';
  if (origin === 'France') return 'French';
  if (origin === 'Germany') return 'German';
  if (origin === 'Italy') return 'Italian';
  if (origin === 'Spain' || origin === 'Mexico' || origin === 'Argentina') return 'Spanish';
  if (origin === 'Brazil') return 'Portuguese';
  if (origin === 'Iran') return 'Persian';
  if (origin === 'Denmark' || origin === 'Sweden') return 'Scandinavian';
  return 'English';
}

function inferPlatforms(year: number, origin: string, tags: string[]): StreamingPlatform[] {
  if (year >= 2025) return ['Theaters', 'Netflix', 'Prime Video'];
  if (origin === 'India') {
    if (tags.includes('comedy') || tags.includes('romance')) return ['Netflix', 'Prime Video', 'ZEE5'];
    return ['Prime Video', 'Netflix', 'Hotstar'];
  }
  if (tags.includes('arthouse') || origin === 'France' || origin === 'Iran' || origin === 'Japan') {
    return ['MUBI', 'Prime Video'];
  }
  return ['Netflix', 'Prime Video', 'Apple TV+'];
}

