const CLEAN_MOVIE_TUPLES = EXPANDED_MOVIE_TUPLES;

export const EXPANDED_MOVIES: CatalogItem[] = CLEAN_MOVIE_TUPLES.map(
  ([id, title, year, creator, origin, rating, tags, moods, summary, whyNotable, extra]) => ({
    id,
    title,
    category: 'movies',
    year,
    era: eraFromYear(year),
    creator,
    tags,
    moods,
    rating,
    isNew: year >= 2024,
    origin,
    durationOrFormat: extra?.duration ?? 'Feature Film',
    summary,
    whyNotable,
    franchise: extra?.franchise,
    platforms: extra?.platforms ?? inferPlatforms(year, origin, tags),
    industry: extra?.industry ?? inferIndustry(origin),
    cast: extra?.cast,
    language: inferLanguage(origin, extra?.language),
    awards: extra?.awards,
    wikiPage: extra?.wikiPage,
  })
);
